extern "C" unsigned __nfcxx_nctaid_y(void);
extern "C" unsigned __nfcxx_nctaid_z(void);


constexpr int helper_default_m = 4;


                                  
template <int N, typename T, int M = helper_default_m>
void helper_affine(const T * in, T * out, int n, T s) {
    int i = __nfcxx_ctaid_x() * __nfcxx_ntid_x() + __nfcxx_tid_x();
    if (i < n) {
        out[i] = in[i] * s + (T)(N * 10 + M);
    }
}
extern "C" void __nfcxx_k_helper_affine_2_float_4(const float * in, float * out, int n, float s) { helper_affine<2, float, 4>(in, out, n, s); }
